@classmethod
def for_assignment(cls, targets: tuple[ast.expr, ...] | list[ast.expr]) -> Self:
    binding = LexicalValueReference.from_expression(targets[0]) if len(targets) == 1 else None
    return cls(CompactValueDestinationKind.EMBEDDED) if binding is None else cls(CompactValueDestinationKind.BOUND, binding)

def _capture_result(
    self, expression: ast.expr | None, destination: CompactValueDestination,
    statement: SourcePositionedNode,
) -> CompactEvaluatedResult:
    if isinstance(expression, ast.Call):
        self.call_results[id(expression)] = destination
    value_use = None if expression is None else self._capture_value(expression)
    result = CompactEvaluatedResult(
        destination, value_use, self._position(), SourceByteSpan.require_node(statement),
    )
    self.evaluated_results.append(result)
    return result

