def visit_Assign(self, node: ast.Assign) -> None:
    result = self._capture_result(
        node.value, CompactValueDestination.for_assignment(node.targets), node
    )
    mutations = self._visit_mutation_targets(node.targets, CompactMutationKind.ASSIGNMENT)
    self._record_exact_value_aliases(node.targets, result.lexical_reference, mutations)

def visit_AnnAssign(self, node: ast.AnnAssign) -> None:
    source = None
    if node.value is None:
        self.mutation_targets.visit(node.target)
        if not (isinstance(node.target, ast.Name) and self.owner.kind.is_function_scope):
            return
    else:
        result = self._capture_result(
            node.value, CompactValueDestination.for_assignment((node.target,)), node
        )
        source = result.lexical_reference
    mutations = self._visit_mutation_targets((node.target,), CompactMutationKind.ASSIGNMENT)
    self._record_exact_value_aliases((node.target,), source, mutations)
